/* =========================================================
   BÀI HỌC — tuần 2 (ngày 10) đến tuần 21.
   Bảy bài đầu (tuần 1 và 2 ngày 8–9) nằm thẳng trong bai-hoc.html vì
   chúng dài gấp ba: đó là những chủ điểm bạn đang sai trong bài viết,
   nên chúng được viết kỹ hơn phần còn lại. Từ đây trở đi là dạng gọn.

   MỖI BÀI GIỮ NGUYÊN BỐN PHẦN CỦA TRANG NÀY:
   why    — vì sao tiếng Anh cần điểm ngữ pháp này
   bridge — tiếng Việt chở đúng thông tin đó bằng dụng cụ gì
   lose   — bỏ đi thì người đọc mất thông tin nào
   blocks — luật, ví dụ ĐÚNG/SAI, bảng, mẹo
   quiz   — 8 câu tự chấm

   w, i  = tuần và chỉ số chủ điểm trong WEEKS[w-1].topics[i] của data.js.
   Nhờ vậy tiêu đề bài học và ngày học KHÔNG BAO GIỜ lệch khỏi lộ trình:
   sửa data.js là trang này đổi theo. Ngày = (w-1)*7 + i + 1.

   ĐỊNH DẠNG NHỎ BÊN TRONG:
   ex   : ['ok'|'no', 'câu tiếng Anh', 'ghi chú ngắn (tuỳ chọn)']
   tbl  : [[cột1, cột2, cột3], ...] — dòng đầu là tiêu đề
   quiz : [câu có đúng một ___, đáp án, giải thích, [lựa chọn]]
   ========================================================= */

