  why:'Đây là bài thực hành, không phải bài luật. Một đoạn văn tốt ở mức B1–B2 có <b>cấu trúc cố định</b> — và cấu trúc đó học được trong một buổi, khác hẳn với việc học ngữ pháp.',
  bridge:[['Câu chủ đề → luận cứ → ví dụ → kết','Topic sentence → support → example → conclusion']],
